export const TOPOLOGY_LAYOUT_PREFERRED_CONNECTOR_ROUTING = {
    ring: "obstacle-aware",
    linear: "straight",
    fishspine: "straight",
    "radial-sectors": "obstacle-aware",
    "orbital-clusters": "obstacle-aware",
    spiral: "obstacle-aware",
    "cascade-tree": "obstacle-aware",
    swimlanes: "obstacle-aware",
    fan: "straight",
    matrix: "obstacle-aware",
    basin: "obstacle-aware",
    "paired-comparison": "obstacle-aware",
    territories: "obstacle-aware",
    custom: "obstacle-aware",
};
export function resolveTopologyLayoutConnectorRouting(topologyLayout) {
    return TOPOLOGY_LAYOUT_PREFERRED_CONNECTOR_ROUTING[topologyLayout];
}
export function createTopologySceneConfig(config) {
    const viewportFit = config.viewportFit ?? config.layout === "viewport-fit";
    const connectorRouting = config.connectorRouting ??
        resolveTopologyLayoutConnectorRouting(config.topologyLayout ?? "custom");
    return {
        ...config,
        viewportFit,
        connectorRouting,
        topologyLayout: config.topologyLayout ?? "custom",
    };
}
